import { User, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { Patient } from "../lib/storage";

export interface PatientSummaryCardProps {
    patient: Patient;
    onReset: () => void;
    className?: string;
}

export function PatientSummaryCard({ patient, onReset, className }: PatientSummaryCardProps) {
    const patientDisplayName = patient.full_name || `${patient.first_name || ''} ${patient.last_name || ''}`.trim() || 'Patient';

    return (
        <div
            className={cn(
                "group relative flex items-center justify-between h-10 px-3 rounded-full mt-0.5",
                "bg-card border border-border/80 dark:border-border/60 hover:border-primary/40 dark:hover:border-primary/40",
                "shadow-xs transition-all duration-200 overflow-hidden select-none",
                className
            )}
        >
            {/* Left: Avatar + Info in single line */}
            <div className="flex items-center gap-2 min-w-0 flex-1 mr-1">
                {/* Compact Avatar */}
                <div className="relative size-6.5 shrink-0 rounded-full bg-primary/10 dark:bg-primary/20 text-primary border border-primary/20 flex items-center justify-center">
                    <User className="size-3.5 text-primary stroke-[2.2]" />
                    <span className="absolute -bottom-0.5 -right-0.5 size-1.5 rounded-full bg-emerald-500 ring-1 ring-card" />
                </div>

                {/* Patient Name & Metadata */}
                <div className="flex items-center gap-1.5 min-w-0 truncate">
                    <span className="text-xs font-semibold text-foreground tracking-tight truncate leading-none">
                        {patientDisplayName}
                    </span>

                    {patient.dob && (
                        <span className="text-[11px] font-mono text-muted-foreground whitespace-nowrap opacity-80 leading-none shrink-0">
                            · DOB: {patient.dob}
                        </span>
                    )}

                    {patient.emr_id && (
                        <span className="text-[10px] font-mono text-muted-foreground whitespace-nowrap opacity-75 leading-none shrink-0">
                            · ID: {patient.emr_id}
                        </span>
                    )}
                </div>
            </div>

            {/* Right: Sleek Change Button */}
            <Button
                variant="ghost"
                size="sm"
                onClick={onReset}
                className="h-7 px-2 rounded-full text-muted-foreground hover:text-primary hover:bg-primary/10 border-0 active:scale-95 transition-all duration-200 gap-1 font-medium text-[11px] group/btn shrink-0 cursor-pointer"
                title="Change selected patient"
            >
                <RefreshCw className="size-3 text-muted-foreground/80 group-hover/btn:text-primary transition-transform duration-500 ease-out group-hover/btn:rotate-180" />
                <span className="tracking-tight hidden sm:inline">Change</span>
            </Button>
        </div>
    );
}
